# (vedi crea_teoria_seo.py): scheda, 3 lezioni a blocchi con domande, riepilogo, domande finali, verifica, prova veloce.
# Le simulazioni di SEA e Brand non ci sono ancora: niente campo "pratica" (la pagina mostra "in arrivo"). Il Social ce l'ha dal 30/10/2026.
# Testi scritti da Claude: DA RILEGGERE.
import json
def singola(testo, giusta, sbagliate, spiega): return {"tipo": "singola", "testo": testo, "opzioni": [{"t": giusta, "giusta": True}] + [{"t": s, "giusta": False} for s in sbagliate], "spiegazione": spiega}
def multipla(testo, giuste, sbagliate, spiega): return {"tipo": "multipla", "testo": testo, "opzioni": [{"t": g, "giusta": True} for g in giuste] + [{"t": s, "giusta": False} for s in sbagliate], "spiegazione": spiega}
def vf(testo, vero, spiega): return {"tipo": "vf", "testo": testo, "risposta": vero, "spiegazione": spiega}
def ordina(testo, voci, spiega): return {"tipo": "ordina", "testo": testo, "voci": voci, "spiegazione": spiega}
def abbina(testo, coppie, spiega): return {"tipo": "abbina", "testo": testo, "coppie": coppie, "spiegazione": spiega}
def blocco(titolo, testo, esempio, domande, blog=None):
    b = {"titolo": titolo, "testo": testo, "esempio": esempio, "domande": domande}
    if blog: b["blog"] = blog
    return b
def lezione(id, titolo, minuti, blocchi, riepilogo, finali, parole):
    return {"id": id, "titolo": titolo, "minuti": minuti, "blocchi": blocchi, "riepilogo": riepilogo, "finali": finali, "parole": parole}
